0:
{
  # Global options
  admin :2019
  log {
    level DEBUG
  }
  servers {
    #trusted_proxies static private_ranges 100.96.0.0/11 # 信任局域网的XFF头
    protocols h1 h2 h3
  }
  crowdsec {
    api_url http://crowdsec-service.security.svc.cluster.local:8080
    api_key {$CROWDSEC_API_KEY}
    ticker_interval 15s
    #appsec_url http://crowdsec-agent:7422
  }
}

:8080 {
  handle /health {
    respond "OK" 200
  }
}

(with-tls) {
  tls /etc/caddy/tls/tls.crt /etc/caddy/tls/tls.key
}
*.{$MAIN_DOMAIN} {
  import with-tls

  route {

    crowdsec

    # 转发所有流量到 external gateway
    handle {
      reverse_proxy {
        to https://envoy-external.network.svc.cluster.local:443
        transport http {
          tls
          tls_server_name {http.request.host}
        }
      }
      header {
        +My-Server "caddy-external"
        -Server
        -via
      }
    }
  }
}

resolver kube-dns.kube-system.svc.cluster.local valid=5s;
server {
  listen 443 ssl;
  ssl_certificate /certs/tls.crt;
  ssl_certificate_key /certs/tls.key;

  set $gitlab_host '$GITLAB_MIRROR_HOST';

  location / {
    proxy_pass $GITLAB_MIRROR_URL;
    proxy_ssl_certificate /client-certs/client.crt;
    proxy_ssl_certificate_key /client-certs/client.key;
    proxy_ssl_verify off;
    proxy_ssl_server_name on;
    proxy_set_header Host $gitlab_host;
    proxy_set_header PRIVATE-TOKEN $http_private_token;
    proxy_set_header Authorization $http_authorization;

    sub_filter_types application/json;
    sub_filter_once off;
    sub_filter '$GITLAB_MIRROR_URL' 'https://gitlab-proxy';
  }
}
